"use client";
/* Termi, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Termi(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("termi"); }, []);
  return React.createElement("piix-pal", { "pal": "termi", ...piixAttrs(props) });
}

export default Termi;
